function withdrawRaisedCapital()
    external
    virtual
    onlyProject
    whenNotPaused
    whenRefundPeriodIsOver
    whenSaleNotCanceled
    whenSaleResultsArePublished
    whenTokensSupplied
{
    // Verify that the project can withdraw capital
    _verifyCanWithdrawCapital();

